[
  {
    "name": "领队老陈",
    "description": "经验丰富的川西高山向导，沉稳可靠，是整支队伍的定海神针",
    "appearance": "45 岁藏族汉子，古铜色皮肤，黝黑短发，颧骨略高原红，眼神深邃平静",
    "costume": "深灰色冲锋衣、黑色抓绒内胆、登山帽、头灯",
    "personality": "话不多但句句有用，对雪山有敬畏也有柔情"
  },
  {
    "name": "女摄影师苏晚",
    "description": "都市来的年轻风光摄影师，背负使命来拍日照金山",
    "appearance": "28 岁，短发清爽，眉眼明亮有灵气",
    "costume": "红色冲锋衣、黑色工装裤、双肩摄影包",
    "personality": "执着、感性、热爱自然"
  },
  {
    "name": "驴友阿杰",
    "description": "活泼的年轻徒步爱好者",
    "appearance": "25 岁，戴棒球帽，笑容灿烂",
    "costume": "亮橙色冲锋衣",
    "personality": "热情、爱玩闹、调节气氛"
  }
]

[
  {
    "name": "川西高原盘山公路",
    "description": "蜿蜒的柏油路穿越高山草甸，云层压在山腰",
    "visualStyle": "横屏 16:9 公路电影构图，冷灰色调，云海翻涌，路两边金黄草甸"
  },
  {
    "name": "海拔 4200 米星空营地",
    "description": "高原平缓草甸上的帐篷营地，背后是连绵雪峰",
    "visualStyle": "横屏 16:9 宽广地平线构图，夜间银河横亘天顶，冷蓝夜空与帐篷暖黄灯火形成对比"
  },
  {
    "name": "营地篝火区",
    "description": "帐篷前的空地，中央燃起篝火",
    "visualStyle": "暖橙火光为主光源，照亮人物面部，背景深邃星空"
  },
  {
    "name": "高原海子（湖泊）",
    "description": "雪山脚下清澈的高原湖，湖面如镜倒映星空与雪峰",
    "visualStyle": "极简构图，水平线居中，水面反射增强"
  },
  {
    "name": "雪山观景平台",
    "description": "营地旁的山脊高点，正对主峰，是观看日照金山的绝佳位置",
    "visualStyle": "前景冷蓝阴影，中景雪峰主体，背景破晓天空"
  },
  {
    "name": "日照金山主峰",
    "description": "海拔 6000 米以上的金字塔形雪山主峰",
    "visualStyle": "日出第一缕金光打在峰顶，下半截仍处于冷蓝阴影，金色与冷蓝强烈对比"
  }
]
